theorem barrier_lt_iff_cross {C₁ C₂ g₁ g₂ : ℕ}
    (hg₁ : 0 < g₁) (hg₂ : 0 < g₂) :
    (C₁ : ℚ) / g₁ < (C₂ : ℚ) / g₂ ↔ C₁ * g₂ < C₂ * g₁

theorem coeff_mul_top {f g : LaurentPolynomial R} {a b : ℤ}
    (hf : Bounded f a) (hg : Bounded g b) :
    (f * g).coeff (a + b) = f.coeff a * g.coeff b

theorem cancel_common_determinant {d p m : ℝ}
    (hd : 0 < d) (hp : 0 < p) (hm : 0 < m) :
    Real.log (d * m) - Real.log (d * p) = scalarOffset p m

theorem projector_offset_eq_transverse_sq {c s : ℝ}
    (hnorm : c^2 + s^2 = 1) :
    1 - c^2 = s^2

theorem projector_offset_eq_trace_defect {c s t : ℝ}
    (hnorm : c^2 + s^2 = 1) (htrace : t = 2*c) :
    s^2 = 1 - (t/2)^2

theorem same_overlap_sq_same_offset {c₁ c₂ : ℝ}
    (h : c₁^2 = c₂^2) :
    1 - c₁^2 = 1 - c₂^2

theorem sufficient_constant_on_fiber {X Y Z : Type*}
    (F : X → Y) (T : X → Z) (h : SufficientObservation F T)
    {x₁ x₂ : X} (hf : F x₁ = F x₂) : T x₁ = T x₂

theorem fiber_witness_obstructs_sufficiency {X Y Z : Type*}
    (F : X → Y) (T : X → Z) {x₁ x₂ : X}
    (hf : F x₁ = F x₂) (ht : T x₁ ≠ T x₂) :
    ¬ SufficientObservation F T

theorem collision_persists_under_postcompression {X Y Z : Type*}
    (F : X → Y) (G : Y → Z) {x₁ x₂ : X} (hf : F x₁ = F x₂) :
    (G ∘ F) x₁ = (G ∘ F) x₂

theorem witness_persists_under_postcompression {X Y Z W : Type*}
    (F : X → Y) (G : Y → Z) (T : X → W) {x₁ x₂ : X}
    (hf : F x₁ = F x₂) (ht : T x₁ ≠ T x₂) :
    ¬ SufficientObservation (G ∘ F) T

theorem three_reading_error_combination {e10 e01 e11 δ : ℝ}
    (h10 : |e10| ≤ δ) (h01 : |e01| ≤ δ) (h11 : |e11| ≤ δ) :
    |e11 - e10 - e01| ≤ 3*δ

theorem inverse_le_chord {a b x : ℝ}
    (ha : 0 < a) (hax : a ≤ x) (hxb : x ≤ b) :
    1/x ≤ inverseChord a b x

theorem inverse_penalty_monotone {w d₀ d₁ z : ℝ}
    (hw : 0 ≤ w) (hz : z < d₀) (hd : d₀ ≤ d₁) :
    w/(d₁-z) ≤ w/(d₀-z)
